import fitz
doc = fitz.open('/root/latex_paper.pdf')

# Check page 1 more carefully - any display math?
page = doc[0]
# Look for common equation markers
for text in ['\\\\frac', '\\\\sum', '\\\\prod']:
    results = page.search_for(text)
    if results:
        print(f'Page 1 {text}: {results}')

# Also search for equation-like patterns
blocks = page.get_text('dict')['blocks']
for block in blocks:
    if 'lines' in block:
        for line in block['lines']:
            text = ''
            for span in line['spans']:
                text += span['text']
            # Look for lines that might be equations (short, contain math symbols)
            if any(c in text for c in ['∑', '∏', '∫', '⟨', '⟩']) and len(text) < 100:
                print(f'Possible eq on p1: {text} at y={line[\"bbox\"][1]:.0f}')
"
